const gcd = (a, b) => {
    const key = 'g:' + a + ':' + b;
    if (map.has(key)) return map.get(key);

    while (b !== 0) {
        [a, b] = [b, a % b];
    }

    map.set(key, a);
    return a;
};

const lcm = (a, b) => {
    const key = 'l:' + a + ':' + b;
    if (map.has(key)) return map.get(key);

    if (a === 0 || b === 0) {
        map.set(key, 0);
        return 0;
    }

    const res = Math.abs(a * b) / gcd(a, b);
    map.set(key, res);
    return res;
};

